import{_ as p}from"./plugin-vue_export-helper-c27b6911.js";import{r as o,o as c,c as l,d as s,e as n,b as t,w as e,a as i,f as r}from"./app-31ccb12c.js";const d={},u=s("p",null,"把语音前端放进真实设备：VoIP、远场助手、会议、媒体播放四类场景的分层与数据流；实时线程、无锁缓冲、perf/ftrace/cyclictest、NEON/定点、功耗与量产问题。",-1),k=s("p",null,"这一篇更偏工程：怎么让算法在目标板上稳定跑住，而不只是「能跑」。",-1),m=r(`<h2 id="_4-端侧语音处理架构与性能调优" tabindex="-1"><a class="header-anchor" href="#_4-端侧语音处理架构与性能调优" aria-hidden="true">#</a> 4. 端侧语音处理架构与性能调优</h2><h3 id="_4-1-分层架构与典型数据流" tabindex="-1"><a class="header-anchor" href="#_4-1-分层架构与典型数据流" aria-hidden="true">#</a> 4.1 分层架构与典型数据流</h3><p><strong>分层</strong>：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>┌─────────────────────────────────────────────┐
│ 应用层：ASR / 唤醒词 / 通话 / 录音 / 媒体播放      │
├─────────────────────────────────────────────┤
│ 语音前端（AFE）：HPF → BF → AEC → NS → AGC → VAD │
├─────────────────────────────────────────────┤
│ 音频服务：ALSA-lib / tinyalsa / PulseAudio      │
├─────────────────────────────────────────────┤
│ 内核：ASoC / DMA / clock / power                 │
├─────────────────────────────────────────────┤
│ 硬件：SoC I2S/PDM、Codec、功放、麦克风阵列         │
└─────────────────────────────────────────────┘
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>场景一：VoIP 通话（双向、强实时）</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>麦克风 → HPF → AEC（参考=远端下行）→ NS → AGC → Opus 编码 → 网络
网络 → jitter buffer → Opus 解码 → 混音 → 扬声器
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>AEC 是核心，参考信号必须与扬声器实际播放严格对齐。</li><li>延迟预算 60—150 ms；蓝牙耳机链路更紧。</li><li>双讲不能断字，NLP 要保守。</li></ul><p><strong>场景二：远场语音助手（唤醒 + ASR）</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>4/6 麦 → PDM → 抽取 → BF（DOA）→ AEC → NS → AGC → VAD → KWS → ASR
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><ul><li>唤醒词常驻低功耗 DSP，主核休眠。</li><li>唤醒后开主链路，波束指向说话人。</li><li>延迟可放宽（100—300 ms），但误唤醒率和功耗是硬指标。</li></ul><p><strong>场景三：录音/会议</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>多麦 → BF → 去混响 → NS → AGC → 多轨/混音 → 编码/存储
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><ul><li>更看重音质与可懂度，可用更复杂的算法和更长帧。</li><li>需要处理削波、风噪、桌子振动。</li></ul><p><strong>场景四：媒体播放</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>解码 → 混音 → 音量 → 限幅 → SRC → ALSA → DAC → 功放
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><ul><li>重点是音质、pop、SRC 质量、多路混音不削波。</li></ul><p><strong>always-on 唤醒词架构</strong>：</p><ul><li>一级 KWS 跑在 DSP/低功耗核，只做「疑似唤醒」检测，功耗 &lt; 1—2 mW。</li><li>二级 KWS 在主核复核，降低误唤醒。</li><li>麦克风常开，需要低噪声 LDO、PDM 时钟门控、DMA 小缓冲。</li></ul><p><strong>异构划分</strong>：</p><table><thead><tr><th>任务</th><th>适合的核</th><th>原因</th></tr></thead><tbody><tr><td>AEC/NS/BF</td><td>DSP（HiFi/Hexagon/CEVA）</td><td>定点高效、实时性好、省主核</td></tr><tr><td>唤醒词</td><td>低功耗 DSP/NPU</td><td>常开、极低功耗</td></tr><tr><td>大模型 NS/ASR</td><td>主核 + NPU</td><td>算力需求大</td></tr><tr><td>控制/路由</td><td>主核</td><td>逻辑复杂</td></tr></tbody></table><h3 id="_4-2-实时性设计" tabindex="-1"><a class="header-anchor" href="#_4-2-实时性设计" aria-hidden="true">#</a> 4.2 实时性设计</h3><p>音频线程是<strong>软实时</strong>：错过一个 period 就是 xrun（可听见的爆音/卡顿）。目标是<strong>最坏情况延迟（WCET）可控</strong>，而不是平均吞吐。</p><p><strong>线程与调度</strong>：</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token keyword">struct</span> <span class="token class-name">sched_param</span> sp <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span>sched_priority <span class="token operator">=</span> <span class="token number">20</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token function">pthread_setschedparam</span><span class="token punctuation">(</span><span class="token function">pthread_self</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> SCHED_FIFO<span class="token punctuation">,</span> <span class="token operator">&amp;</span>sp<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token function">mlockall</span><span class="token punctuation">(</span>MCLK_CURRENT <span class="token operator">|</span> MCLK_FUTURE<span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">/* 锁内存，避免 page fault */</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>音频线程优先级通常 <strong>10—30</strong>；IRQ 线程 50—90；不要用 99（会饿死内核线程）。</li><li><code>SCHED_FIFO</code> 无时间片，同级按 FIFO；确保不会死循环。</li><li>避免优先级反转：用带优先级继承的 mutex（<code>PTHREAD_PRIO_INHERIT</code>），或干脆无锁。</li><li>关键线程绑核（<code>sched_setaffinity</code>），避免迁移带来的 cache 抖动。</li></ul><p><strong>回调里绝对不能做的事</strong>：</p><ul><li><code>malloc/free</code>、<code>new/delete</code>（可能拿锁、触发 page fault）。</li><li><code>printf/fprintf</code>、syslog（I/O 阻塞）。</li><li>文件/网络 I/O、<code>sleep</code>。</li><li>大块 <code>memcpy</code>（可接受，但要评估）。</li><li>加锁等待（尤其与低优先级线程共享）。</li><li>浮点异常/除零（提前检查）。</li></ul><p><strong>无锁环形缓冲（单生产者单消费者）</strong>：</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token keyword">typedef</span> <span class="token keyword">struct</span> <span class="token punctuation">{</span>
    <span class="token keyword">float</span> <span class="token operator">*</span>buf<span class="token punctuation">;</span>
    <span class="token class-name">size_t</span>  size<span class="token punctuation">;</span>          <span class="token comment">/* 2 的幂 */</span>
    <span class="token keyword">_Atomic</span> <span class="token class-name">size_t</span> w<span class="token punctuation">,</span> r<span class="token punctuation">;</span>
<span class="token punctuation">}</span> <span class="token class-name">ring_t</span><span class="token punctuation">;</span>

<span class="token keyword">static</span> <span class="token keyword">inline</span> <span class="token class-name">size_t</span> <span class="token function">ring_write</span><span class="token punctuation">(</span><span class="token class-name">ring_t</span> <span class="token operator">*</span>q<span class="token punctuation">,</span> <span class="token keyword">const</span> <span class="token keyword">float</span> <span class="token operator">*</span>src<span class="token punctuation">,</span> <span class="token class-name">size_t</span> n<span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token class-name">size_t</span> w <span class="token operator">=</span> <span class="token function">atomic_load_explicit</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>q<span class="token operator">-&gt;</span>w<span class="token punctuation">,</span> memory_order_relaxed<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">size_t</span> r <span class="token operator">=</span> <span class="token function">atomic_load_explicit</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>q<span class="token operator">-&gt;</span>r<span class="token punctuation">,</span> memory_order_acquire<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">size_t</span> space <span class="token operator">=</span> q<span class="token operator">-&gt;</span>size <span class="token operator">-</span> <span class="token punctuation">(</span>w <span class="token operator">-</span> r<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>n <span class="token operator">&gt;</span> space<span class="token punctuation">)</span> n <span class="token operator">=</span> space<span class="token punctuation">;</span>
    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token class-name">size_t</span> i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> n<span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span>
        q<span class="token operator">-&gt;</span>buf<span class="token punctuation">[</span><span class="token punctuation">(</span>w <span class="token operator">+</span> i<span class="token punctuation">)</span> <span class="token operator">&amp;</span> <span class="token punctuation">(</span>q<span class="token operator">-&gt;</span>size <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">]</span> <span class="token operator">=</span> src<span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token function">atomic_store_explicit</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>q<span class="token operator">-&gt;</span>w<span class="token punctuation">,</span> w <span class="token operator">+</span> n<span class="token punctuation">,</span> memory_order_release<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">return</span> n<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>要点：读写指针单调递增、用掩码取模、acquire/release 保证可见性、容量取 2 的幂。</p><p><strong>PREEMPT_RT</strong>：</p><ul><li>把大部分内核临界区变成可抢占，降低最坏调度延迟。</li><li>中断线程化（<code>devm_request_threaded_irq</code>），音频 IRQ 线程可设优先级。</li><li>关中断/关抢占区间仍会造成抖动，需要 <code>cyclictest</code> 验证。</li><li>不是万能药：驱动里的长临界区、DMA 回调、电源管理仍可能引入 ms 级抖动。</li></ul><p><strong>其他</strong>：</p><ul><li><code>CONFIG_HZ</code>、<code>NO_HZ_FULL</code>、CPU isolation（<code>isolcpus</code>）减少干扰。</li><li>关闭 CPU 调频的激进策略（<code>performance</code> governor）可降低抖动，代价是功耗。</li><li>避免在音频线程里触发频率切换/热插拔。</li></ul><h3 id="_4-3-性能剖析工具链" tabindex="-1"><a class="header-anchor" href="#_4-3-性能剖析工具链" aria-hidden="true">#</a> 4.3 性能剖析工具链</h3><table><thead><tr><th>目的</th><th>工具</th><th>关键用法</th></tr></thead><tbody><tr><td>CPU 热点</td><td><code>perf</code></td><td><code>perf top -p &lt;pid&gt;</code>、<code>perf record -g</code>、<code>perf report</code></td></tr><tr><td>调度延迟</td><td><code>perf sched</code></td><td><code>perf sched latency</code>、<code>perf sched record</code></td></tr><tr><td>函数耗时</td><td><code>ftrace</code></td><td><code>function_graph</code>、<code>set_ftrace_filter=snd_pcm_*</code></td></tr><tr><td>系统级跟踪</td><td><code>trace-cmd</code></td><td><code>trace-cmd record -p function_graph -g &#39;snd_*&#39;</code></td></tr><tr><td>实时性</td><td><code>cyclictest</code></td><td><code>cyclictest -t -p80 -n -i1000 -l10000</code></td></tr><tr><td>硬件延迟</td><td><code>hwlatdetect</code></td><td>检测 SMI/固件引起的停顿</td></tr><tr><td>中断分布</td><td><code>/proc/interrupts</code></td><td>看 I2S/DMA 中断是否集中在一个核</td></tr><tr><td>功耗</td><td><code>powertop</code>、<code>turbostat</code></td><td>看 C-state、频率、唤醒源</td></tr><tr><td>内存</td><td><code>valgrind --tool=massif</code>、<code>heaptrack</code></td><td>找实时线程里的分配</td></tr><tr><td>系统调用</td><td><code>strace -T</code></td><td>看 ioctl/read 的耗时</td></tr></tbody></table><p><strong>perf 示例</strong>：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>perf record <span class="token parameter variable">-F</span> <span class="token number">999</span> <span class="token parameter variable">-g</span> <span class="token parameter variable">-p</span> <span class="token variable"><span class="token variable">$(</span>pidof my_audio_app<span class="token variable">)</span></span> -- <span class="token function">sleep</span> <span class="token number">10</span>
perf report <span class="token parameter variable">--stdio</span> <span class="token operator">|</span> <span class="token function">head</span> <span class="token parameter variable">-50</span>
perf <span class="token function">stat</span> <span class="token parameter variable">-e</span> cycles,instructions,cache-misses,branch-misses <span class="token parameter variable">-p</span> <span class="token operator">&lt;</span>pid<span class="token operator">&gt;</span> -- <span class="token function">sleep</span> <span class="token number">5</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>ftrace 示例</strong>：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token builtin class-name">cd</span> /sys/kernel/debug/tracing
<span class="token builtin class-name">echo</span> function_graph <span class="token operator">&gt;</span> current_tracer
<span class="token builtin class-name">echo</span> <span class="token string">&#39;snd_pcm_*&#39;</span> <span class="token operator">&gt;</span> set_ftrace_filter
<span class="token builtin class-name">echo</span> <span class="token number">1</span> <span class="token operator">&gt;</span> tracing_on
<span class="token comment"># 跑一段音频</span>
<span class="token builtin class-name">echo</span> <span class="token number">0</span> <span class="token operator">&gt;</span> tracing_on
<span class="token function">cat</span> trace <span class="token operator">|</span> <span class="token function">head</span> <span class="token parameter variable">-100</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>cyclictest 示例</strong>：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>cyclictest <span class="token parameter variable">-t</span> <span class="token parameter variable">-p80</span> <span class="token parameter variable">-n</span> <span class="token parameter variable">-i1000</span> <span class="token parameter variable">-l10000</span> <span class="token parameter variable">-m</span>
<span class="token comment"># 关注 Max Latency；音频场景希望 &lt; 200 us（RT 内核），普通内核可能 1—5 ms</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-4-优化手段与顺序" tabindex="-1"><a class="header-anchor" href="#_4-4-优化手段与顺序" aria-hidden="true">#</a> 4.4 优化手段与顺序</h3><p><strong>先测量，再优化</strong>。推荐顺序：</p><ol><li><strong>算法层</strong>：降采样、缩短滤波器、减少 FFT 点数、用子带/稀疏、模型量化/剪枝。</li><li><strong>数据层</strong>：定点化、减少内存带宽、合并循环、避免重复计算。</li><li><strong>指令层</strong>：NEON/SIMD、查表、SIMD 友好的数据布局（planar）。</li><li><strong>系统层</strong>：绑核、优先级、DMA 零拷贝、缓存友好、减少唤醒。</li><li><strong>硬件层</strong>：DSP offload、NPU、更大 cache、独立 SRAM。</li></ol><p><strong>NEON 示例（FIR 单点内积，卷积的内层循环）</strong>：</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;arm_neon.h&gt;</span></span>

<span class="token keyword">float</span> <span class="token function">dot_neon</span><span class="token punctuation">(</span><span class="token keyword">const</span> <span class="token keyword">float</span> <span class="token operator">*</span>x<span class="token punctuation">,</span> <span class="token keyword">const</span> <span class="token keyword">float</span> <span class="token operator">*</span>h<span class="token punctuation">,</span> <span class="token keyword">int</span> n<span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token class-name">float32x4_t</span> acc <span class="token operator">=</span> <span class="token function">vdupq_n_f32</span><span class="token punctuation">(</span><span class="token number">0.0f</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">int</span> i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">+</span> <span class="token number">4</span> <span class="token operator">&lt;=</span> n<span class="token punctuation">;</span> i <span class="token operator">+=</span> <span class="token number">4</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token class-name">float32x4_t</span> xv <span class="token operator">=</span> <span class="token function">vld1q_f32</span><span class="token punctuation">(</span>x <span class="token operator">+</span> i<span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token class-name">float32x4_t</span> hv <span class="token operator">=</span> <span class="token function">vld1q_f32</span><span class="token punctuation">(</span>h <span class="token operator">+</span> i<span class="token punctuation">)</span><span class="token punctuation">;</span>
        acc <span class="token operator">=</span> <span class="token function">vmlaq_f32</span><span class="token punctuation">(</span>acc<span class="token punctuation">,</span> xv<span class="token punctuation">,</span> hv<span class="token punctuation">)</span><span class="token punctuation">;</span>      <span class="token comment">/* acc += xv * hv */</span>
    <span class="token punctuation">}</span>
    <span class="token class-name">float32x2_t</span> s <span class="token operator">=</span> <span class="token function">vadd_f32</span><span class="token punctuation">(</span><span class="token function">vget_low_f32</span><span class="token punctuation">(</span>acc<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token function">vget_high_f32</span><span class="token punctuation">(</span>acc<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">return</span> <span class="token function">vget_lane_f32</span><span class="token punctuation">(</span><span class="token function">vpadd_f32</span><span class="token punctuation">(</span>s<span class="token punctuation">,</span> s<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>注意：AArch64 可用 <code>vaddvq_f32</code> 一次求和；AArch32 用上面的成对加法。实时 FIR 通常用「块处理 + 多相」进一步减少开销。</p><p><strong>定点 Q15 示例</strong>：</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token keyword">static</span> <span class="token keyword">inline</span> <span class="token class-name">int16_t</span> <span class="token function">q15_mul</span><span class="token punctuation">(</span><span class="token class-name">int16_t</span> a<span class="token punctuation">,</span> <span class="token class-name">int16_t</span> b<span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token class-name">int32_t</span> p <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token class-name">int32_t</span><span class="token punctuation">)</span>a <span class="token operator">*</span> b <span class="token operator">+</span> <span class="token number">0x4000</span><span class="token punctuation">;</span>   <span class="token comment">/* 四舍五入 */</span>
    p <span class="token operator">&gt;&gt;=</span> <span class="token number">15</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>p <span class="token operator">&gt;</span> <span class="token number">32767</span><span class="token punctuation">)</span>  p <span class="token operator">=</span> <span class="token number">32767</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>p <span class="token operator">&lt;</span> <span class="token operator">-</span><span class="token number">32768</span><span class="token punctuation">)</span> p <span class="token operator">=</span> <span class="token operator">-</span><span class="token number">32768</span><span class="token punctuation">;</span>
    <span class="token keyword">return</span> <span class="token punctuation">(</span><span class="token class-name">int16_t</span><span class="token punctuation">)</span>p<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>定点 vs 浮点</strong>：</p><table><thead><tr><th>维度</th><th>定点（Q15/Q31）</th><th>浮点</th></tr></thead><tbody><tr><td>功耗/面积</td><td>低</td><td>高</td></tr><tr><td>动态范围</td><td>需精心定标，易溢出/底噪</td><td>大，开发快</td></tr><tr><td>确定性</td><td>完全确定</td><td>受舍入/denormal 影响</td></tr><tr><td>SIMD</td><td>NEON 整数乘加高效</td><td>NEON 浮点也快（A55+）</td></tr><tr><td>适用</td><td>DSP、低端 MCU、量产</td><td>主核、算法原型</td></tr></tbody></table><p><strong>denormal 处理</strong>：极小浮点数会让 CPU 进入慢路径。启用 flush-to-zero：</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token comment">/* AArch64 */</span>
<span class="token class-name">uint64_t</span> fpcr<span class="token punctuation">;</span>
__asm__ <span class="token keyword">volatile</span><span class="token punctuation">(</span><span class="token string">&quot;mrs %0, fpcr&quot;</span> <span class="token operator">:</span> <span class="token string">&quot;=r&quot;</span><span class="token punctuation">(</span>fpcr<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
fpcr <span class="token operator">|=</span> <span class="token punctuation">(</span><span class="token number">1ULL</span> <span class="token operator">&lt;&lt;</span> <span class="token number">24</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                 <span class="token comment">/* FZ */</span>
__asm__ <span class="token keyword">volatile</span><span class="token punctuation">(</span><span class="token string">&quot;msr fpcr, %0&quot;</span> <span class="token operator">::</span> <span class="token string">&quot;r&quot;</span><span class="token punctuation">(</span>fpcr<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>或给滤波器状态注入极小的抖动噪声，避免长时间静音后状态衰减到 denormal 区间。</p><p><strong>CPU 预算参考</strong>（16 kHz 单通道，Cortex-A53 单核，量级）：</p><table><thead><tr><th>模块</th><th>CPU 占用</th></tr></thead><tbody><tr><td>HPF / DC</td><td>&lt; 0.5%</td></tr><tr><td>4 麦波束成形</td><td>5—15%</td></tr><tr><td>AEC（200 ms 尾长，PBFDAF）</td><td>5—15%</td></tr><tr><td>NS（STFT + 传统）</td><td>3—8%</td></tr><tr><td>NS（轻量 DNN）</td><td>10—30%</td></tr><tr><td>AGC + VAD</td><td>1—3%</td></tr><tr><td>Opus 编码（16 kHz）</td><td>2—5%</td></tr></tbody></table><p>合计 20—50% 单核；48 kHz 全带宽通常再翻 1.5—2 倍。<strong>留 30% 余量</strong>给突发和系统抖动。</p><p><strong>功耗优化</strong>：</p><ul><li>常开 KWS 放 DSP，主核深度睡眠。</li><li>批处理/合并唤醒，减少 CPU 进出 C-state。</li><li>动态降采样（安静时 8 kHz，检测到语音切 16 kHz）。</li><li>关闭未用麦克风/通道。</li><li>选择低功耗 codec 与 Class-D 功放，注意静态电流。</li><li>温度高时降频会引发 xrun，要留余量。</li></ul><h3 id="_4-5-测试、验证与量产问题" tabindex="-1"><a class="header-anchor" href="#_4-5-测试、验证与量产问题" aria-hidden="true">#</a> 4.5 测试、验证与量产问题</h3><p><strong>延迟测试</strong>：</p><ul><li>环回（loopback）：播放脉冲 → 录音，测峰值间隔，减去已知 buffer。</li><li><code>latmus</code>（alsa-tools）测 ALSA 往返。</li><li>示波器/逻辑分析仪测 BCLK/LRCLK 与模拟输出的相位。</li><li>端到端：人工嘴 + 人工耳，测 mouth-to-ear。</li></ul><p><strong>音质测试</strong>：</p><ul><li>THD+N、SNR、频响、串扰、最大输出、底噪。</li><li>设备：Audio Precision、QA401/QA402、REW + 测量麦。</li><li>播放扫频/白噪声，录音后分析。</li></ul><p><strong>时钟与漂移</strong>：</p><ul><li>长时间录 1 kHz 正弦，测相位漂移；或对比两个时钟域的样本数。</li><li>验证 ASRC/反馈重采样是否收敛。</li></ul><p><strong>稳定性</strong>：</p><ul><li>72 小时 soak，统计 xrun 次数、内存增长、句柄泄漏。</li><li>反复插拔耳机、切换采样率、suspend/resume。</li><li>低电量/高温/高负载下的 xrun。</li></ul><p><strong>语音质量</strong>：</p><ul><li>PESQ/STOI/DNSMOS；真实场景录音回放。</li><li>ASR WER、唤醒率/误唤醒率（每天次数）。</li><li>双讲、回声、风噪、键盘声、音乐噪声。</li></ul><p><strong>量产常见问题</strong>：</p><table><thead><tr><th>问题</th><th>根因</th><th>对策</th></tr></thead><tbody><tr><td>个别机器有底噪</td><td>麦克风一致性/PCB 地线</td><td>产线校准、筛选</td></tr><tr><td>大声时破音</td><td>AOP 不足/增益过大</td><td>降 PGA、加限幅、选高 AOP 麦</td></tr><tr><td>回声投诉</td><td>AEC 参考延迟/非线性</td><td>校准延迟、加强 NLP、结构隔振</td></tr><tr><td>啸叫</td><td>扬声器-麦克风耦合</td><td>降低增益、移频/陷波、结构优化</td></tr><tr><td>偶发卡顿</td><td>调度/中断/电源管理</td><td>RT 优先级、绑核、关调频</td></tr><tr><td>蓝牙延迟大</td><td>编解码/重传/缓冲</td><td>LE Audio、调小 buffer、编解码选型</td></tr></tbody></table><hr>`,74),v=s("strong",null,"系列导航",-1),b=s("strong",null,"下一篇",-1);function g(h,_){const a=o("RouterLink");return c(),l("div",null,[s("blockquote",null,[s("p",null,[n("本文是「设备端音频与语音处理」系列第 4 篇（共 7 篇）。系列导览："),t(a,{to:"/source-study/audio/"},{default:e(()=>[n("从 pipeline 到 Linux 音频栈")]),_:1}),n("。")])]),u,k,i(" more "),m,s("p",null,[v,n("："),t(a,{to:"/source-study/audio/"},{default:e(()=>[n("系列导览")]),_:1}),n(" · "),b,n("："),t(a,{to:"/source-study/audio/05-interview-basics-algorithms.html"},{default:e(()=>[n("设备端音频（五）：面试问答 30 题（基础与算法）")]),_:1})])])}const x=p(d,[["render",g],["__file","04-embedded-speech-architecture.html.vue"]]);export{x as default};
